    'web-server-log-analyzer':{fields:[S('format','日誌格式','combined',[['combined','Apache／Nginx Combined'],['common','Common Log']]),T('input','Access Log','203.0.113.10 - - [23/Aug/2026:10:12:01 +0800] "GET /tools HTTP/1.1" 200 1842 "https://example.com/" "Mozilla/5.0"\n203.0.113.11 - - [23/Aug/2026:10:12:05 +0800] "GET /missing HTTP/1.1" 404 512 "-" "curl/8.0"\n203.0.113.10 - - [23/Aug/2026:10:13:09 +0800] "POST /api/test HTTP/1.1" 500 90 "https://example.com/" "Mozilla/5.0"')],run:v=>{const pattern=/^(\S+)\s+\S+\s+\S+\s+\[([^\]]+)\]\s+"(\S+)\s+([^\s"]+)(?:\s+[^"]+)?"\s+(\d{3})\s+(\d+|-)\s*(?:"([^"]*)"\s+"([^"]*)")?/,items=[],bad=[];for(const [i,line] of lines(req(v.input)).filter(Boolean).entries()){const m=line.match(pattern);if(!m){bad.push(i+1);continue}items.push({ip:m[1],time:m[2],method:m[3],path:m[4],status:+m[5],bytes:m[6]==='-'?0:+m[6],referer:m[7]||'',agent:m[8]||''})}const countBy=fn=>Object.entries(items.reduce((o,x)=>{const k=fn(x);o[k]=(o[k]||0)+1;return o},{})).sort((a,b)=>b[1]-a[1]),report={requests:items.length,totalBytes:items.reduce((s,x)=>s+x.bytes,0),uniqueIps:new Set(items.map(x=>x.ip)).size,statusCodes:Object.fromEntries(countBy(x=>x.status)),methods:Object.fromEntries(countBy(x=>x.method)),topPaths:countBy(x=>x.path).slice(0,10).map(([path,count])=>({path,count})),clientFamilies:{browser:items.filter(x=>/Mozilla/i.test(x.agent)).length,cli:items.filter(x=>/curl|wget|httpie/i.test(x.agent)).length,other:items.filter(x=>x.agent&&!/Mozilla|curl|wget|httpie/i.test(x.agent)).length},unparsedLines:bad};return R(JSON.stringify(report,null,2),'Web 伺服器日誌已分析',[['請求',items.length],['狀態錯誤',items.filter(x=>x.status>=400).length],['未解析列',bad.length]],{statusType:bad.length?'warn':'ok',filename:'access-log-report.json',mime:'application/json'})}},
